Image *ReadGroup4Image(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image = NULL;
  FILE *file = NULL;
  FILE *temp_file = NULL;
  size_t length;
  ssize_t count;
  ssize_t row;
  MagickBooleanType status = MagickFalse;
  char buffer[MagickPathExtent];

  assert(image_info != (const ImageInfo *) NULL);
  assert(image != (Image *) NULL);
  (void) CopyMagickString(buffer, GetImageInfoBlob(image_info), MagickPathExtent);

  if ((file = fopen(buffer, "rb")) == (FILE *) NULL)
    ThrowFileException(exception, FileOpenError, "UnableToOpenFile", buffer);

  /* Create a temporary file to write TIFF headers and data */
  if ((temp_file = TemporaryFile()) == (FILE *) NULL)
    ThrowFileException(exception, FileOpenError, "UnableToCreateTemporaryFile", "temporary");

  /* Write TIFF headers and image data to the temporary file */
  for (row = 0; row < (ssize_t) image->rows; row++)
  {
    count = fread(image->pixels, sizeof(*image->pixels), (size_t) image->columns, file);
    if (count != (ssize_t) image->columns)
    {
      fclose(temp_file);
      fclose(file);
      ThrowFileException(exception, CorruptImageError, "UnableToReadImageData", buffer);
    }

    if (fwrite(image->pixels, sizeof(*image->pixels), (size_t) image->columns, temp_file) != (size_t) image->columns)
    {
      fclose(temp_file);
      fclose(file);
      ThrowFileException(exception, FileWriteError, "UnableToWriteImageData", "temporary");
    }
  }

  fclose(file);
  rewind(temp_file);

  /* Read the TIFF image from the temporary file into memory */
  image = ReadImage(image_info, temp_file, exception);
  if (image == (Image *) NULL)
  {
    fclose(temp_file);
    return (Image *) NULL;
  }

  /* Set the filename and format fields of the Image structure */
  SetImageFilename(image, "Group4 TIFF");
  SetImageFormat(image, "TIFF");

  fclose(temp_file);

  return image;
}

