Image *
ReadGroup4Image(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image = NULL;
  FILE *file = NULL;
  FILE *temp_file = NULL;
  size_t data_size;
  unsigned char *data = NULL;

  /* Validate input parameters */
  if (!image_info || !exception)
    return NULL;

  /* Open the input image file */
  file = fopen(image_info->filename, "rb");
  if (!file)
  {
    (void) ThrowFileException(exception, FileOpenError, image_info->filename,
      image_info->filename);
    return NULL;
  }

  /* Determine data size and allocate memory */
  fseek(file, 0, SEEK_END);
  data_size = (size_t) ftell(file);
  rewind(file);

  data = (unsigned char *) AcquireMemory(data_size);
  if (!data)
  {
    fclose(file);
    (void) ThrowMemoryException(exception);
    return NULL;
  }

  /* Read image data */
  if (fread(data, 1, data_size, file) != data_size)
  {
    fclose(file);
    RelinquishMemory(data);
    (void) ThrowFileException(exception, FileReadError, image_info->filename,
      image_info->filename);
    return NULL;
  }

  /* Open temporary file for TIFF output */
  temp_file = TemporaryFile();
  if (!temp_file)
  {
    fclose(file);
    RelinquishMemory(data);
    (void) ThrowFileException(exception, TemporaryFileError, image_info->filename,
      image_info->filename);
    return NULL;
  }

  /* Write TIFF headers and data to temporary file */
  if (fwrite(data, 1, data_size, temp_file) != data_size)
  {
    fclose(file);
    fclose(temp_file);
    RelinquishMemory(data);
    (void) ThrowFileException(exception, FileWriteError, image_info->filename,
      image_info->filename);
    return NULL;
  }

  /* Create image structure */
  image = CreateImage(image_info, exception);
  if (!image)
  {
    fclose(file);
    fclose(temp_file);
    RelinquishMemory(data);
    return NULL;
  }

  /* Populate image filename and format */
  (void) CopyString(image->filename, image_info->filename);
  (void) CopyString(image->format, "TIFF");

  /* Clean up */
  fclose(file);
  fclose(temp_file);
  RelinquishMemory(data);

  return image;
}

Image *ReadTIFFImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image = NULL;
  FILE *file = NULL;
  FILE *temp_file = NULL;
  char temp_filename[MaxTextExtent];

  assert(image_info != NULL);
  assert(exception != NULL);

  /* Open the input image file */
  file = fopen(image_info->filename, "rb");
  if (file == NULL)
  {
    (void) ThrowMagickException(exception, GetMagickModule(), FileOpenError,
      "Unable to open file", "%s", image_info->filename);
    return NULL;
  }

  /* Create a temporary file to write TIFF data */
  (void) FormatLocaleString(temp_filename, MaxTextExtent, "%s.tiff", image_info->filename);
  temp_file = fopen(temp_filename, "wb");
  if (temp_file == NULL)
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), FileOpenError,
      "Unable to open temporary file", "%s", temp_filename);
    return NULL;
  }

  /* Write TIFF header and image data */
  if (!WriteTIFFHeader(temp_file, image_info, exception))
  {
    (void) fclose(file);
    (void) fclose(temp_file);
    return NULL;
  }

  if (!WriteTIFFData(temp_file, file, exception))
  {
    (void) fclose(file);
    (void) fclose(temp_file);
    return NULL;
  }

  (void) fclose(file);
  (void) fclose(temp_file);

  /* Read the TIFF image from the temporary file */
  image = ReadImage(image_info, temp_filename, exception);
  if (image == NULL)
  {
    (void) unlink(temp_filename);
    return NULL;
  }

  image->filename = AcquireString(image_info->filename);
  image->format = TIFF;

  return image;
}
